"""Migration of the Meridian CRM nightly case-escalation job."""

from datetime import date


def _text(value: object) -> str:
    """Mirror legacy empty-string behavior for missing/uninitialized values."""
    return "" if value is None else str(value)


def _parse_yyyymmdd(value: object) -> date | None:
    text = _text(value)
    if not text or text == "00000000" or len(text) != 8 or not text.isdigit():
        return None

    try:
        return date(int(text[:4]), int(text[4:6]), int(text[6:8]))
    except ValueError:
        return None


def _datediff(day1: object, day2: object) -> int:
    """Return whole calendar days day1 - day2, or zero for null/sentinel dates."""
    first = _parse_yyyymmdd(day1)
    second = _parse_yyyymmdd(day2)
    if first is None or second is None:
        return 0
    return (first - second).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events for overdue live support cases."""
    events: list[dict] = []
    emitted_ids: set[str] = set()

    for case in sorted(cases, key=lambda row: _text(row.get("CASE_ID"))):
        if _text(case.get("DEL_FLG")) == "Y":
            continue

        case_id = _text(case.get("CASE_ID"))
        if case_id in emitted_ids:
            continue

        age = _datediff(today, case.get("OPEN_DT"))
        status = _text(case.get("STAT_CD"))

        overdue_new = status == "N" and age >= 2
        overdue_assigned = (
            status == "A"
            and _text(case.get("ESC_FLG")) != "Y"
            and age >= 7
        )

        if overdue_new or overdue_assigned:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": case_id,
                    "event": "auto_escalate",
                }
            )
            emitted_ids.add(case_id)

    return events
